{"command":"$root = (Get-Location).Path
$patterns = @('Review_Strict_V*.md','idea_review_v*.md')
$files = @()
if (Get-Command rg -ErrorAction SilentlyContinue) {
  $files = rg --files --hidden --no-ignore -g 'Review_Strict_V*.md' -g 'idea_review_v*.md' | ForEach-Object { Join-Path $root $_ }
} else {
  $files = Get-ChildItem -Path . -Recurse -Force -File -Include $patterns -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }
}
$resolved = $files | ForEach-Object { Resolve-Path -LiteralPath $_ -ErrorAction SilentlyContinue } | ForEach-Object { $_.Path } | Sort-Object -Unique
$outside = $resolved | Where-Object { -not $_.StartsWith($root, [System.StringComparison]::OrdinalIgnoreCase) }
if ($outside) { throw "Refusing delete; outside workspace: $($outside -join ', ')" }
$grouped = $resolved | ForEach-Object {
  if ($_ -like "*\server_snapshot\*") { 'server_snapshot' }
  elseif ($_ -like "*\paper_workflow_remote_runs\*") { 'paper_workflow_remote_runs' }
  elseif ($_ -like "*\idea\*") { 'idea' }
  else { 'repo_root' }
} | Group-Object | Sort-Object Name
$grouped | ForEach-Object { [PSCustomObject]@{Category=$_.Name; Count=$_.Count} } | Format-Table -AutoSize
"TOTAL=$($resolved.Count)"","workdir":"D:\Shervin\OneDrive\Desktop\breaking","timeout_ms":30000}

