)
foreach ($id in $ids) {
  $enc = [uri]::EscapeDataString($id)
  $uri = "https://api2.openreview.net/invitations?id=$enc"
  "ID: $id"
  try {
    $resp = Invoke-RestMethod -Uri $uri -Method Get -TimeoutSec 20
    "count=$($resp.count) invitations=$($resp.invitations.Count)"
    if ($resp.invitations.Count -gt 0) {
      $inv = $resp.invitations[0]
      $inv.id
      $inv.edit.note.content | ConvertTo-Json -Depth 8
    }
  } catch { "ERROR: $($_.Exception.Message)" }
  ""
}","workdir":"D:\Shervin\OneDrive\Desktop\breaking","timeout_ms":30000}

